create table if not exists public.social_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null,actor_id uuid references auth.users(id) on delete set null,payload jsonb not null default '{}'::jsonb,read_at timestamptz,created_at timestamptz not null default now());create index if not exists social_notifications_user_idx on public.social_notifications(user_id,created_at desc);alter table public.social_notifications enable row level security;revoke all on public.social_notifications from anon,authenticated;grant select,update,delete on public.social_notifications to authenticated;create policy social_notifications_owner_select on public.social_notifications for select to authenticated using(user_id=(select auth.uid()));create policy social_notifications_owner_update on public.social_notifications for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy social_notifications_owner_delete on public.social_notifications for delete to authenticated using(user_id=(select auth.uid()));create or replace function public.send_friend_request(p_target uuid) returns void language plpgsql security definer set search_path='' as $$begin if p_target=(select auth.uid()) then raise exception 'SELF_FRIEND';end if;if exists(select 1 from public.social_blocks where(blocker_id=(select auth.uid()) and blocked_id=p_target)or(blocker_id=p_target and blocked_id=(select auth.uid())))then raise exception 'BLOCKED';end if;if exists(select 1 from public.friend_requests where status in('pending','accepted') and((sender_id=(select auth.uid())and receiver_id=p_target)or(sender_id=p_target and receiver_id=(select auth.uid()))))then return;end if;insert into public.friend_requests(sender_id,receiver_id)values((select auth.uid()),p_target);insert into public.social_notifications(user_id,type,actor_id)values(p_target,'FRIEND_REQUEST',(select auth.uid()));end;$$;create or replace function public.respond_friend_request(p_sender uuid,p_accept boolean) returns void language plpgsql security definer set search_path='' as $$begin update public.friend_requests set status=case when p_accept then'accepted' else'rejected'end,updated_at=now() where sender_id=p_sender and receiver_id=(select auth.uid())and status='pending';if found and p_accept then insert into public.social_notifications(user_id,type,actor_id)values(p_sender,'FRIEND_ACCEPTED',(select auth.uid()));end if;end;$$;revoke all on function public.send_friend_request(uuid),public.respond_friend_request(uuid,boolean) from public,anon;grant execute on function public.send_friend_request(uuid),public.respond_friend_request(uuid,boolean) to authenticated;